import { Suspense } from 'react'
import { unstable_prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

// Opt this route into Partial Prefetching, so an ordinary (viewport/hover)
// prefetch only fetches the static shell.
export const prefetch = 'partial'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={null}>
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Everything below this is left out of the shell — and therefore out of the
  // default prefetch — but is still included in a `<Link prefetch={true}>`
  // prefetch, so it is already in the client cache by navigation time.
  await unstable_prefetch()
  const relatedProducts = await getRelatedProducts()

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

